begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data) select ('50000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'vote-sql-'||n||'@example.invalid',jsonb_build_object('username','VoteSQL'||n) from generate_series(1,6) n;
insert into auth.sessions(id,user_id) select id,id from public.profiles where id::text like '50000000-%';
update private.authz set role='critic' where user_id='50000000-0000-0000-0000-000000000003';
update private.authz set role='moderator' where user_id='50000000-0000-0000-0000-000000000004';
update private.authz set role='admin' where user_id='50000000-0000-0000-0000-000000000005';
insert into public.manual_games(id,title,synopsis,platforms,genres,source_url,source_label) values('50000000-0000-0000-0000-000000000099','Isolated vote SQL fixture','Isolated SQL only, never live provider data.',array['PC'],array['Test'],'https://example.com/isolated-vote-sql','Isolated test');
insert into public.manual_games(id,title,synopsis,platforms,genres,source_url,source_label) select ('52000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'Isolated vote target '||n,'Isolated SQL only, never live provider data.',array['PC'],array['Test'],'https://example.com/isolated-vote-'||n,'Isolated test' from generate_series(1,125) n;
insert into public.reviews(id,author_id,manual_game_id,rating,title,body_public,author_active) select ('51000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'50000000-0000-0000-0000-000000000001',('52000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,7,'Vote target','An isolated public opinion sufficiently long.',true from generate_series(1,125) n;
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000001','50000000-0000-0000-0000-000000000001','vote',array['51000000-0000-0000-0000-000000000001']::uuid[],1)$$,'42501',null,'no auto vote');
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000006','vote',array['51000000-0000-0000-0000-000000000001']::uuid[],1)$$,'42501',null,'session belongs to voter');
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000001']::uuid[],0)$$,'22023',null,'zero vote rejected');
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000001']::uuid[],null)$$,'22023',null,'null vote rejected');
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','delete',array['51000000-0000-0000-0000-000000000001']::uuid[],1)$$,'22023',null,'unsupported operation rejected');
select lives_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000001']::uuid[],1)$$,'role 2 votes as participant');
select lives_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000003','50000000-0000-0000-0000-000000000003','vote',array['51000000-0000-0000-0000-000000000001']::uuid[],-1)$$,'role 3 votes as participant');
select lives_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000004','50000000-0000-0000-0000-000000000004','vote',array['51000000-0000-0000-0000-000000000001']::uuid[],1)$$,'role 4 votes as participant');
select lives_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000005','50000000-0000-0000-0000-000000000005','vote',array['51000000-0000-0000-0000-000000000001']::uuid[],1)$$,'role 5 votes as participant');
select is((select helpful_count from public.reviews where id='51000000-0000-0000-0000-000000000001'),3,'three useful votes');
select is((select unhelpful_count from public.reviews where id='51000000-0000-0000-0000-000000000001'),1,'one unhelpful vote');
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000001']::uuid[],-1)$$,'23505',null,'duplicate cannot switch sign');
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000001']::uuid[],1)$$,'23505',null,'duplicate cannot repeat');
select throws_ok($$update public.review_votes set value=-1 where voter_id='50000000-0000-0000-0000-000000000002'$$,'42501',null,'historical votes immutable');
update private.authz set role='admin',status='suspended' where user_id='50000000-0000-0000-0000-000000000002';
select is((select value::int from public.review_votes where voter_id='50000000-0000-0000-0000-000000000002'),1,'role and suspension retain sign');
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000002']::uuid[],1)$$,'42501',null,'suspended voter denied');
update private.authz set status='active' where user_id='50000000-0000-0000-0000-000000000002';
delete from auth.sessions where id='50000000-0000-0000-0000-000000000006';
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000006','50000000-0000-0000-0000-000000000006','vote',array['51000000-0000-0000-0000-000000000002']::uuid[],1)$$,'42501',null,'revoked session denied');
update public.reviews set status='withdrawn' where id='51000000-0000-0000-0000-000000000002';
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000002']::uuid[],1)$$,'42501',null,'withdrawn denied');
update public.reviews set status='hidden' where id='51000000-0000-0000-0000-000000000002';
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000002']::uuid[],1)$$,'42501',null,'hidden denied');
update public.reviews set status='published' where id='51000000-0000-0000-0000-000000000002';
update private.authz set status='suspended' where user_id='50000000-0000-0000-0000-000000000001';
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000002']::uuid[],1)$$,'42501',null,'suspended author denied');
select is((select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','own',array['51000000-0000-0000-0000-000000000001']::uuid[],null)->'votes'->0->>'value'),'1'::text,'own vote recoverable on suspended author');
select is((select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','own',array['51000000-0000-0000-0000-000000000001']::uuid[],null)->'votes'->0->>'helpfulCount'),null::text,'ineligible counts private');
update private.authz set status='active' where user_id='50000000-0000-0000-0000-000000000001';
set local role anon;
select throws_ok($$insert into public.review_votes(review_id,voter_id,value) values(gen_random_uuid(),gen_random_uuid(),1)$$,'42501',null,'anon cannot insert');
select throws_ok($$update public.review_votes set value=-1$$,'42501',null,'anon cannot update');
select throws_ok($$delete from public.review_votes$$,'42501',null,'anon cannot delete');
select throws_ok($$update public.reviews set helpful_count=999$$,'42501',null,'anon cannot forge count');
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000001']::uuid[],1)$$,'42501',null,'anon cannot invoke private RPC');
select throws_ok($$select * from public.review_votes$$,'42501',null,'anon cannot read vote identities');
reset role;
set local role authenticated;
select throws_ok($$insert into public.review_votes(review_id,voter_id,value) values(gen_random_uuid(),gen_random_uuid(),1)$$,'42501',null,'authenticated cannot insert');
select throws_ok($$update public.review_votes set value=-1$$,'42501',null,'authenticated cannot update');
select throws_ok($$delete from public.review_votes$$,'42501',null,'authenticated cannot delete');
select throws_ok($$update public.reviews set helpful_count=999$$,'42501',null,'authenticated cannot forge count');
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000001']::uuid[],1)$$,'42501',null,'authenticated cannot invoke private RPC');
reset role;
set local role service_role;
select throws_ok($$insert into public.review_votes(review_id,voter_id,value) values(gen_random_uuid(),gen_random_uuid(),1)$$,'42501',null,'service_role cannot insert');
select throws_ok($$update public.review_votes set value=-1$$,'42501',null,'service_role cannot update');
select throws_ok($$delete from public.review_votes$$,'42501',null,'service_role cannot delete');
select throws_ok($$update public.reviews set helpful_count=999$$,'42501',null,'service_role cannot forge count');
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000001']::uuid[],1)$$,'42501',null,'service_role cannot invoke private RPC');
select throws_ok($$select * from public.review_votes$$,'42501',null,'service_role cannot read vote identities');
reset role;
select set_config('request.jwt.claims','{"sub":"50000000-0000-0000-0000-000000000001","session_id":"50000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.review_votes),0,'RLS role 1 sees only own votes');
reset role;
select set_config('request.jwt.claims','{"sub":"50000000-0000-0000-0000-000000000002","session_id":"50000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.review_votes),1,'RLS role 2 sees only own votes');
reset role;
select set_config('request.jwt.claims','{"sub":"50000000-0000-0000-0000-000000000003","session_id":"50000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.review_votes),1,'RLS role 3 sees only own votes');
reset role;
select set_config('request.jwt.claims','{"sub":"50000000-0000-0000-0000-000000000004","session_id":"50000000-0000-0000-0000-000000000004","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.review_votes),1,'RLS role 4 sees only own votes');
reset role;
select set_config('request.jwt.claims','{"sub":"50000000-0000-0000-0000-000000000005","session_id":"50000000-0000-0000-0000-000000000005","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.review_votes),1,'RLS role 5 sees only own votes');
reset role;
select set_config('request.jwt.claims','{"sub":"50000000-0000-0000-0000-000000000006","session_id":"50000000-0000-0000-0000-000000000006","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.review_votes),0,'RLS role 6 sees only own votes');
reset role;
create function pg_temp.fail_vote_audit() returns trigger language plpgsql as $$begin raise exception 'Isolated vote audit fault'; end;$$;
create trigger isolated_vote_audit_fault before insert on private.audit_logs for each row execute function pg_temp.fail_vote_audit();
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000002']::uuid[],1)$$,'P0001',null,'audit fault aborts vote');
select is((select count(*)::int from public.review_votes where review_id='51000000-0000-0000-0000-000000000002'),0,'failed audit no vote');
select is((select helpful_count from public.reviews where id='51000000-0000-0000-0000-000000000002'),0,'failed audit no count');
drop trigger isolated_vote_audit_fault on private.audit_logs;
select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array[('51000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid],1) from generate_series(2,20) n;
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000021']::uuid[],1)$$,'P0429',null,'twenty per rolling minute');
alter table public.review_votes disable trigger review_vote_immutable;
update public.review_votes set created_at=clock_timestamp()-interval '61 seconds' where voter_id='50000000-0000-0000-0000-000000000002';
alter table public.review_votes enable trigger review_vote_immutable;
select lives_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000021']::uuid[],1)$$,'expired minute permits vote');
alter table public.review_votes disable trigger review_vote_immutable;
insert into public.review_votes(review_id,voter_id,value,created_at) select ('51000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'50000000-0000-0000-0000-000000000002',1,(date_trunc('day',clock_timestamp() at time zone 'UTC') at time zone 'UTC') from generate_series(22,100) n;
alter table public.review_votes enable trigger review_vote_immutable;
select throws_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000101']::uuid[],1)$$,'P0429',null,'hundred per UTC day');
alter table public.review_votes disable trigger review_vote_immutable;
update public.review_votes set created_at=(date_trunc('day',clock_timestamp() at time zone 'UTC') at time zone 'UTC')-interval '1 microsecond' where voter_id='50000000-0000-0000-0000-000000000002';
alter table public.review_votes enable trigger review_vote_immutable;
select lives_ok($$select private.review_vote_operation('50000000-0000-0000-0000-000000000002','50000000-0000-0000-0000-000000000002','vote',array['51000000-0000-0000-0000-000000000101']::uuid[],1)$$,'prior UTC day excluded');
delete from public.review_votes where review_id='51000000-0000-0000-0000-000000000001' and voter_id='50000000-0000-0000-0000-000000000004';
select is((select helpful_count from public.reviews where id='51000000-0000-0000-0000-000000000001'),2,'operator cleanup decrements count');
delete from auth.users where id='50000000-0000-0000-0000-000000000005';
select is((select helpful_count from public.reviews where id='51000000-0000-0000-0000-000000000001'),1,'voter cascade decrements count');
delete from public.reviews where id='51000000-0000-0000-0000-000000000001';
select is((select count(*)::int from public.review_votes where review_id='51000000-0000-0000-0000-000000000001'),0,'review cascade removes votes');
select * from finish();
rollback;
